cssContent:
/* Kumori paper theme for Boomi Flow (2026-10-05) */
:root{--k-paper:#f5f5f4;--k-card:#ffffff;--k-stripe:#efefed;--k-line:#e7e7e5;--k-ink:#1b1b1a;--k-ink2:#595855;--k-amber:#e8a33a;--k-amber-text:#8a5a12}
body,.flow,.mw-bs{background:var(--k-paper)!important;color:var(--k-ink);font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Helvetica Neue",Arial,sans-serif;line-height:1.6}
section.content,.main-container,.flow>div{max-width:980px;margin:0 auto}
img[src*="favicon.svg"]{width:44px!important;height:44px!important;border-radius:10px}
h1,h2,h3,.page-title{color:var(--k-ink);font-weight:600;letter-spacing:-.01em}
h2{font-size:1.7rem;margin:.6em 0 .4em}h3{font-size:1.15rem;margin:1.4em 0 .4em}
a{color:var(--k-ink);text-decoration-color:var(--k-amber);text-underline-offset:3px}
.page-component-presentation{background:var(--k-card);border:1px solid var(--k-line);border-radius:16px;padding:18px 22px;margin:0 0 16px;box-shadow:0 1px 2px rgba(0,0,0,.04),0 8px 24px rgba(0,0,0,.05)}
.page-component-presentation li{margin:.25em 0}
.button,.btn,button{border-radius:999px!important;padding:9px 20px!important;font-weight:600;border:1.5px solid var(--k-ink)!important;background:var(--k-card)!important;color:var(--k-ink)!important;transition:transform .15s ease,box-shadow .15s ease}
.button:hover,button:hover{transform:translateY(-1px);box-shadow:0 4px 14px rgba(0,0,0,.12)}
.button.submit,.button-outcome.submit{background:var(--k-amber)!important;border-color:var(--k-amber)!important;color:var(--k-ink)!important;font-weight:700}
.table-wrapper{background:var(--k-card);border:1px solid var(--k-line);border-radius:14px;overflow:hidden;box-shadow:0 8px 24px rgba(0,0,0,.05)}
table{width:100%;border-collapse:collapse!important;background:var(--k-card)!important}
table th{background:#fafaf9!important;color:var(--k-amber-text)!important;font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;font-weight:700;border-bottom:1px solid var(--k-line)!important;white-space:nowrap}
table td,table th{padding:12px 14px!important;text-align:left;border-color:var(--k-line)!important}
table tbody tr{background:var(--k-card)!important}
table tbody tr:nth-child(even){background:var(--k-stripe)!important}
table tbody tr:hover{background:#e9e8e4!important}
table td{color:var(--k-ink2)}
table td .button-outcome{padding:5px 14px!important;font-size:.85rem}
.k-num{display:inline-grid;place-items:center;min-width:28px;height:28px;padding:0 6px;margin-right:10px;border-radius:8px;background:var(--k-amber);color:var(--k-ink);font-weight:700;font-size:.8rem}
.k-name{font-weight:600;color:var(--k-ink)}
.k-status{display:inline-flex;align-items:center;gap:6px;padding:3px 10px;border-radius:999px;border:1px solid var(--k-ink2);font-size:.82rem;font-weight:600;color:var(--k-ink)}
.k-status.on{border:2px solid var(--k-ink)}
.k-hide{display:none!important}
@media (prefers-reduced-motion:reduce){.button,button{transition:none}}
@media (max-width:640px){table th:nth-child(3),table td:nth-child(3){display:none}h2{font-size:1.35rem}}

